// PDF Parser with OCR fallback
const binaryData = $input.item.binary.data;
const fileName = binaryData.fileName;
const mimeType = binaryData.mimeType;
const fileSize = binaryData.fileSize;

// Check file size (max 10MB)
if (fileSize > 10 * 1024 * 1024) {
  throw new Error('File size exceeds 10MB limit');
}

// Log processing start
console.log(`Processing PDF file: ${fileName}`);

try {
  // In a real implementation, this would use PyPDF2 or similar
  // For this template, we'll simulate the extraction
  const extractedText = `Simulated text extraction from ${fileName}`;

  // Return the extracted text and metadata
  return {
    json: {
      success: true,
      text: extractedText,
      metadata: {
        source: fileName,
        mimeType: mimeType,
        timestamp: new Date().toISOString(),
        pageCount: 10, // Simulated page count
        fileSize: fileSize
      }
    }
  };
} catch (error) {
  console.log(`Error processing PDF: ${error.message}`);

  // Fallback to OCR (simulated)
  console.log('Falling back to OCR processing');

  return {
    json: {
      success: true,
      text: `OCR extracted text from ${fileName}`,
      metadata: {
        source: fileName,
        mimeType: mimeType,
        timestamp: new Date().toISOString(),
        pageCount: 10, // Simulated
        fileSize: fileSize,
        processedWithOcr: true
      }
    }
  };
}

