// Text Chunking
const text = $input.item.json.text;
const metadata = $input.item.json.metadata;

// Configuration
const chunkSize = 100; // tokens (approximate)
const chunkOverlap = 0.5; // 50% overlap

// Simple chunking function (in a real implementation, this would use a proper tokenizer)
function chunkText(text, chunkSize, overlap) {
  // Simple approximation: 1 token ≈ 4 characters
  const charSize = chunkSize * 4;
  const overlapSize = Math.floor(charSize * overlap);
  const chunks = [];

  let startPos = 0;
  while (startPos < text.length) {
    const endPos = Math.min(startPos + charSize, text.length);
    chunks.push(text.substring(startPos, endPos));
    startPos = endPos - overlapSize;
  }

  return chunks;
}

// Process the text
const chunks = chunkText(text, chunkSize, chunkOverlap);

// Create items for each chunk with metadata
const items = chunks.map((chunk, index) => {
  return {
    json: {
      chunk_id: `${metadata.source.replace(/\.[^/.]+$/, '')}_chunk_${index}`,
      content: chunk,
      metadata: {
        ...metadata,
        chunk_index: index,
        chunk_total: chunks.length,
        chunk_strategy: 'token',
        chunk_size: chunkSize,
        chunk_overlap: chunkOverlap
      }
    }
  };
});

return items;
